JCMethodDecl generateDefaultProvider(BuilderFieldData bfd, JCVariableDecl field) {
	JavacTreeMaker maker = this.getTreeMaker();
	List<JCTypeParameter> params = this.typeParams;
	bfd.nameOfDefaultProvider = this.toName(DEFAULT_PREFIX + bfd.name);
	bfd.nameOfSetFlag = this.toName(bfd.name + SET_PREFIX);
	bfd.builderFieldName = this.toName(bfd.name + VALUE_PREFIX);
	// Lombok tries to keep the position of the original initializer. First we save the expression ...
	JCExpression init = field.init;
	field.init = null;

	// ... then we generate an empty return statement ...
	JCReturn statement = maker.Return(null);
	JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
	int modifiers = Flags.PRIVATE | Flags.STATIC;
	JCMethodDecl defaultProvider = maker.MethodDef(maker.Modifiers(modifiers), bfd.nameOfDefaultProvider, cloneType(maker, bfd.type, bfd.originalFieldNode), JavacHandlerUtil.copyTypeParams(bfd.originalFieldNode, params), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
	// ... then we set positions for everything else ...
	recursiveSetGeneratedBy(defaultProvider, sourceNode);
	// ... and finally add back the original expression
	statement.expr = init;
	return defaultProvider;
}

