JCMethodDecl generateDefaultProvider(BuilderFieldData bfd, JCVariableDecl field) {
	JavacTreeMaker maker = this.getTreeMaker();
	List<JCTypeParameter> params = this.typeParams;
	bfd.nameOfDefaultProvider = this.toName(DEFAULT_PREFIX + bfd.name);
	bfd.nameOfSetFlag = this.toName(bfd.name + SET_PREFIX);
	bfd.builderFieldName = this.toName(bfd.name + VALUE_PREFIX);
	JCStatement statement = maker.Return(field.init);
	field.init = null;
	JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
	int modifiers = Flags.PRIVATE | Flags.STATIC;
	return maker.MethodDef(maker.Modifiers(modifiers), bfd.nameOfDefaultProvider, cloneType(maker, bfd.type, bfd.originalFieldNode), JavacHandlerUtil.copyTypeParams(bfd.originalFieldNode, params), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
}

